insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 1, 'A screening comes back and the reader wants to know what this module will refuse to answer. Where does that list come from?', '["The studio assembles the list from whichever result fields came back empty, so its length depends on which boxes were filled in before the run.", "The engine carries both lists itself and returns them with every screening, 8 items it will not pretend to answer and 11 numbers with no source in the repository.", "Both lists hold 11 entries, one naming the held constants and the other naming the constants the vendored golden pins, and they are returned so the two can be compared.", "The refusals live in the studio help text and the screening carries only the numbers, which is why a caller has to read the documentation to find out what is missing."]'::jsonb, 1, '`NOT_PROVIDED` carries 8 items and `HELD_FOR_LITERATURE` carries 11. `screen` returns both, so a caller shows them rather than discovering them one support call at a time.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 2, 'Ask this studio for a sour service severity region and for the material choice that would follow from one. What comes back?', '["A severity region computed from the H2S partial pressure and then flagged as held, sitting on exactly the same footing as the band label the engine prints beside the rate.", "A null region and a null material string, which a caller is expected to fill from its own materials database.", "A severity region in words with no material recommendation attached, because the second was withdrawn and the first was not.", "Two fields declaring the absence, `regionProvided` false and `materialGuidanceProvided` false, beside a comparison of one partial pressure against one threshold."]'::jsonb, 3, 'The absence is published as a value of its own. A caller reading a missing property cannot tell a deliberate refusal from an unset one, so both flags come back false on every screening.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 3, 'The digest proves the withdrawn severity region is genuinely gone three separate ways. Which of these is one of them?', '["None of the three material guidance strings and neither standard name appears anywhere in the 783 lines of the engine source.", "The function is still exported, and every call to it now returns an error object that names the standard it is no longer willing to cite.", "The vendored golden carries no row for the region, so a case that asked for one would fail the suite.", "The studio hides the region rows behind a disclosure, so nothing reaches the screen even when the field is populated."]'::jsonb, 0, 'The three checks are that `sourServiceRegion` is not exported so typeof it is undefined, that neither standard name nor any of the three guidance strings is anywhere in the source, and that no returned string in three whole screenings names either standard.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 4, 'The expression behind the withdrawn region was not retuned. Why is retuning the wrong repair for that particular defect?', '["Retuning was attempted and the validation suite stayed entirely green all the way through it, so the measurements that would have settled the constants could never be made at all.", "A sour service region comes out as a discrete label rather than as a continuous number, so there is no constant anywhere inside it that a tuning exercise could have moved.", "The number is not where the claim sits. Labelling a curve with a standard''s name claims that the standard says this, and no amount of measurement makes that true.", "The expression depended on a pH that was often absent, and an expression that cannot be fed reliably cannot be fitted reliably either."]'::jsonb, 2, 'A fit out by a factor of two in a number is a tolerance problem and you repair it by measuring. A fit invented and then given somebody else''s authority is a different kind of thing, and the only honest repair is to stop claiming it.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 5, 'The screening threshold the sour door still compares against was left exactly where it was. What is the reasoning?', '["The threshold is the one constant anywhere in this module that carries a published source of its own, so it survived a review that removed a good deal else.", "The threshold is exported by name, and an exported constant cannot be moved without breaking any caller reading it by that name.", "Moving a live number to another unsourced value would repeat the original mistake with the sign flipped, so the engine keeps it and declares it held.", "A threshold only ever drives a boolean flag, so its value cannot reach any number the screening actually prints and there was nothing at all to be gained."]'::jsonb, 2, '`thresholdHeld` comes back true, which is the engine saying the number is not sourced in this repository. The engine prints the threshold in both units so nobody has to guess which one a comparison was made against.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 6, 'A colleague quotes the sour screening threshold as a round 0.05 psia. What is wrong with that, and why can the gap between the two be given as two different percentages?', '["The round figure is not the one the engine works to, and the gap depends on which of the two numbers it is taken as a fraction of.", "The two agree to six decimals in psia and part company only in bar, because the conversion back through the engine''s own factor is what introduces the difference in the first place.", "The round figure is what the studio displays, so the two live at different layers.", "Nothing is wrong with it, since the threshold value is held and a held number carries no precision claim."]'::jsonb, 0, 'As a fraction of the smaller number the gap is 1.526417 percent. Measured against the threshold the engine actually uses, a threshold of exactly 0.05 psia is 1.503467 percent below it. Both are right, and each needs its basis stated beside it.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 7, 'Digest section 3 measures every held constant out of the engine''s behaviour and also prints what the engine exports. Why print both columns?', '["A measurement only reaches a constant that appears in a returned field, so the export column covers the rest.", "An export says what the module declares and a measurement says what it actually uses, so the two disagreeing would itself be a finding.", "One column is what the studio prints behind its disclosure and the other is what the oracle carries.", "Exports are literals and measurements are bisections, so printing both gives the relative difference column something to compare."]'::jsonb, 1, 'The engine exports 15 of the pinned constants. An export agreeing with a measurement checks the export. A measurement on its own checks the behaviour. Both columns are printed so a disagreement would be visible.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 8, 'A paired experiment moved constants in the engine and in the vendored oracle at the same time. What did it show?', '["Every one of the 17 was caught by the suite exactly as written, which is the reason the vendored oracle is treated throughout as an independent second derivation of the engine''s own answers.", "Only the constants that appear in a returned field were caught, so the experiment showed that the suite tests outputs rather than internals.", "The suite failed on all 17, but each failure named the wrong constant.", "15 of 17 constants moved in both files at once left the suite entirely green, because a constant living in two files cannot be validated by comparing those two files."]'::jsonb, 3, 'That is why section 3 compares each measured value against a literal in a THIRD file, and why the golden''s own copy of the constants is treated as a FOURTH. Any two of them agreeing is no longer enough.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 9, 'How many held constants does the digest pin, how many does the engine export by name, and how many does the vendored golden carry in its own block?', '["11 pinned, 8 exported and 17 in the golden, which are the sizes of the two exported lists and of the case block beside them.", "30 pinned, 30 exported and 30 carried in the golden, since the whole point of a pin is to force all three independent copies to hold exactly the same entries.", "30 pinned, 15 exported and 28 in the golden''s own block.", "28 pinned, 15 exported and 30 in the golden, so the generator is the widest of the three copies and the golden the narrowest."]'::jsonb, 2, '30 constants are pinned in section 3, the engine exports 15 of them by name, and the golden''s `heldConstants` block carries 28 that are re-measured against the engine''s behaviour.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 10, 'What kind of quantity is the single rate this engine returns?', '["A general uniform rate, which the engine states in its own list of absences by naming a localised attack rate as something it does not provide.", "A worst case rate over the wetted surface, which is why the band label beside it is described as possibly optimistic by a step or two.", "A rate for the bottom of the line, since the wetting regime and the water cut are what the calculation is built around.", "A general rate with a localised multiplier available separately for welds and bends through a door of its own."]'::jsonb, 0, 'Uniform means metal loss spread over the wetted surface at the stated conditions. It is no kind of pitting rate, weld rate or top of line rate, and the module holds no localised model to compare one against.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 11, 'Four things a reader opens a Corrosion & Integrity studio expecting to find are absent from it. Which set is right?', '["A partial pressure, a wall shear, a remaining life and a binding constraint, none of which this screening returns.", "An inspection interval, a minimum thickness, a retirement thickness and a fitness for service assessment.", "A rate category, a sour flag, a corrosion product regime and a controlling word, all four of which are withheld on every case.", "A design life, an allowance, a consumed depth and a water cut."]'::jsonb, 1, 'All four are in `NOT_PROVIDED`. Producing any of them means adopting a standard this module does not carry, so the course reads the word integrity narrowly as an allowance divided by a rate.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 12, 'This module computes a wall shear. What is it for, and what does its presence not imply?', '["It converts a velocity into a metal loss from entrained solids, which is what erosional wall loss means on a production line.", "It sets the retirement thickness the allowance is measured down to, which is why the allowance and the shear appear on the same rail.", "It is the erosional velocity criterion under another name, given as a stress rather than a velocity.", "It decides whether a corrosion inhibitor film survives, and it is not an erosional velocity limit, which this engine does not have at all."]'::jsonb, 3, 'Mechanical erosion from entrained solids or impingement is not modelled here at all, and the engine carries no erosional velocity criterion. The Casing & Tubing Design course owns that criterion and Nodal Analysis and Gas Well Deliverability cite it.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 13, 'One of the studio''s unit conversions is truncated far more coarsely than the engine''s own factor. Which one, and by how much?', '["The rate conversion to mils a year, where a division by 25.4 and a multiplication by a thousand round before the engine''s own figure does.", "The density conversion, where 16.0185 stands in for a factor the engine exports to twelve figures and carries into the Reynolds number.", "The psig to bar conversion. The studio divides by 14.5038 where the engine exports 14.503773800722, so the studio''s divisor is larger by 1.806e-6 as a fraction.", "The allowance conversion, where a multiplication by 25.4 loses the definition of the inch that the remaining life arithmetic then divides by."]'::jsonb, 2, 'The definitions of the bar and of the pound force give 14.503773773021, and the engine''s factor sits 1.910e-9 above that. The digest measures the engine''s factor out of the psia it reports for a partial pressure of exactly 1 bar.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 14, 'What is that truncated divisor worth on the shipped case, and what follows for this course?', '["Two rates that differ by 1.434e-6 as a fraction, which is why no graded field in this course is converted through the studio.", "Two rates that differ in the second decimal, which is enough to move the band label and is the reason the label is never graded.", "Nothing measurable, because the difference falls below the precision the digest prints and the two conversions give the same double.", "Two rates that differ by 1.806e-6 as a fraction, which is the same figure as the divisor gap because the rate is linear in the pressure."]'::jsonb, 0, 'Through the studio''s divisor the shipped case gives 0.754523654262 mm/yr and through the engine''s factor 0.754524736514 mm/yr. All three capstones therefore state their conditions in the engine''s units.'),
  ('corrosion', 'beginner', 'module', 'm01-what-this-screen-answers-and-what-it-withdrew', 15, 'In this course the word integrity is used narrowly. What does it cover?', '["A fitness for service assessment carried out against a minimum thickness the module computes from the allowance and the consumed depth.", "The barrier envelope argument the Well Integrity and P&A course owns, restated as wall thickness.", "The whole screening, which is why the binding constraint reconciles every field into one verdict.", "One arithmetic, a corrosion allowance divided by a rate, and nothing beyond that."]'::jsonb, 3, 'Reading it narrowly is what keeps the app honest. A screen offering an interval, a thickness and a verdict off the same unsourced chain would look far more useful and be far harder to argue with.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 1, 'A gas analysis gives carbon dioxide at 3 mol% and the engine reports a carbon dioxide partial pressure of 1.530013 bar. What arithmetic produced that figure?', '["The total pressure multiplied by the mole fraction and then by the fugacity coefficient of 0.878581, which is the correction every pressure on this screen carries.", "The mole fraction divided into the total pressure of 51.000427 bar.", "The total pressure of 51.000427 bar multiplied by a mole fraction of 0.030000, with no correlation constant anywhere in the step.", "The fugacity of 1.344240 bar divided by the coefficient of 0.878581."]'::jsonb, 2, 'A partial pressure is the total pressure times the mole fraction. The hydrogen sulphide figure is reached the same way, 0.001000 of the same total pressure giving 0.051000 bar.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 2, 'Partial pressure and fugacity are two numbers for one molecule. On the shipped case, what are they and what sits between them?', '["A partial pressure of 1.530013 bar and a fugacity of 1.344240 bar, with a coefficient of 0.878581 between them.", "A partial pressure of 1.344240 bar and a fugacity of 1.530013 bar, the fugacity being the larger because the coefficient exceeds one on a compressed gas.", "A partial pressure of 1.530013 bar and a fugacity of 1.344240 bar, which the engine reaches by applying the same coefficient it applies to hydrogen sulphide.", "Two figures that agree to six decimals at this pressure, so the studio prints both only because the correlation names one of them."]'::jsonb, 0, 'The coefficient falls below one as the total pressure rises, so the fugacity sits below the partial pressure. At a total pressure of 1.000000 bar the two are 0.030000 bar and 0.029924 bar.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 3, 'Which quantity feeds which calculation in this engine?', '["The partial pressure drives the rate chain, and the fugacity drives the threshold comparison and the corrosion product ratio.", "The fugacity drives everything downstream of the composition, so the threshold comparison and the ratio are both made on corrected quantities.", "The partial pressure drives everything, and the fugacity is reported beside it for a reader who wants the thermodynamic figure.", "The fugacity drives the rate chain, and the partial pressures drive the hydrogen sulphide comparison and the ratio that decides which corrosion product governs."]'::jsonb, 3, 'Both terms of the rate correlation take the fugacity, and so does the film factor and the temperature at which that factor leaves one. Nothing in the rate chain takes the carbon dioxide partial pressure directly.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 4, 'Walk the total pressure up at a fixed composition and read the fugacity coefficient. What happens?', '["It rises with pressure, which is why a high pressure line reports a fugacity above its own partial pressure.", "It falls, from 0.997465 at 1.000000 bar to 0.974938 at 10.000000 bar, 0.880814 at 50.000000 bar and 0.601919 at 200.000000 bar.", "It holds near one until the cap is reached and then drops in a single step to 0.530179, which is the value it is held at above the cap.", "It falls with pressure and with temperature together, so the coefficient cannot be read from the pressure alone at any point on the curve."]'::jsonb, 1, 'At 249.000000 bar it is 0.531526, and above the cap the engine holds it flat and says so in a note. The constants behind that curve are held for literature.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 5, 'At a total pressure of 249.000000 bar the coefficient is 0.531526 and at 400.000000 bar it is 0.530179. What has happened in between?', '["The coefficient passed through a minimum and is now climbing again, which the cap flag records so a reader knows which side of the turn they are on.", "The correlation was extrapolated past its validity band.", "The pressure cap was reached, so the coefficient is held flat at its value there and `pressureCapApplied` turns true.", "Nothing has happened. The difference is the sixth significant figure."]'::jsonb, 2, 'At 249.000000 bar the flag is false and at 251.000000 bar and 400.000000 bar the coefficient is 0.530179 with the flag true, identical to its value at 250.000000 bar.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 6, 'Above the cap the engine returns a note in its own words. What does that note do that silently holding the value would not?', '["It states that the coefficient is held at its 250 bar value and that what the correlation does above the cap is not established here.", "It converts the reported coefficient into a bracket by giving the two values the correlation would take at the ends of its published validity band.", "It refuses the screening outright, which is what stops a rate above the cap from ever reaching a report that somebody else will read later.", "It substitutes the coefficient with the last value the correlation was fitted at and records the substitution in the clamps list beside the other clamped inputs."]'::jsonb, 0, 'The engine''s own words: the fugacity coefficient is held at its 250 bar value: 399.99999999999994 bar is above the cap and what the correlation does above it is not established here. Holding a value flat is a stated convention.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 7, 'What is the standing of the cap itself and of the behaviour above it?', '["The cap is a published validity limit and only the behaviour above it is held, which is why the engine is willing to report a number there.", "Both are measured by bisection, so the value above the cap is a measurement.", "The cap is held and anything above it is refused.", "Both are held for literature, so a screening run above the cap is reporting a convention back to the reader."]'::jsonb, 3, 'Section 21 lists the 250 bar fugacity cap and what the correlation does above it as one held item. No graded field in this course sits above the cap for that reason.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 8, 'A user types 3 into the box that wants a carbon dioxide mole fraction. What does the engine do?', '["It accepts the figure and reports a partial pressure three hundred times the total pressure, since the range guard covers only negative values.", "It refuses and quotes the value back, saying the CO2 mole fraction must be between 0 and 1: 3 is outside it.", "It reads the number as mole percent, divides by a hundred and carries on, which is the conversion the studio layer would have applied.", "It clamps the fraction to 1 and records the clamp in the list of inputs the engine moved, alongside the corrosion inhibitor clamps."]'::jsonb, 1, 'Nought to one on every fraction is one of the range guards this module enforces, alongside nought to fourteen on pH, a temperature above absolute zero, and the partial pressure sum against the total.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 9, 'A blank carbon dioxide box and a carbon dioxide mole fraction of 3 are both refused, and the two messages are different. Why?', '["The blank is caught by the whole screening door and the out of range value by the fugacity door, so the two messages come from two different layers.", "The blank refusal is thrown and the out of range refusal is returned as an object, so a caller sweeping candidate compositions can carry on past the second.", "A blank is a question the engine cannot answer and a 3 is a value it can reject, so one asks for a finite figure and the other names the range and the value.", "The blank is refused by the sum guard, because an absent fraction makes the sum of the two mole fractions impossible to compare against the total."]'::jsonb, 2, 'A blank box gives back that a finite CO2 mole fraction is required. A 3 gives back the range and the value that failed it. A typed zero is a third case again, a positive assertion that there is no carbon dioxide.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 10, 'Three temperatures are refused at the fugacity door. Which description matches what the engine does?', '["All three are clamped to the nearest temperature inside the correlation''s published validity band and the clamp is reported.", "A blank temperature is refused and a temperature below absolute zero is accepted, since the correlation is a function of the reciprocal temperature and stays finite there.", "All three return not a number from the whole screening door, which a caller is expected to test for before reading any field.", "A blank temperature asks for a finite figure, and a temperature at or below absolute zero is refused with the typed value named in the message."]'::jsonb, 3, 'The refusals name the input. A temperature at absolute zero comes back as a temperature above absolute zero is required, with the figure that was typed quoted inside the message.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 11, 'The bare coefficient door returns not a number at a temperature of -300 C rather than a finite figure. Why does that matter?', '["A finite number there would be read as an answer by anything that only tests for an error key.", "A finite number there would be inside the correlation''s published validity band, which the engine has no way of enforcing.", "Not a number is what the studio layer converts into the refusal the user sees, so the bare door has to produce it for the message to exist.", "A ratio below absolute zero comes back negative."]'::jsonb, 0, 'Anything checking only for an error key would take a finite coefficient as a valid one and carry it straight into the rate chain. Not a number cannot be mistaken for an answer.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 12, 'Does this engine apply a fugacity correction to hydrogen sulphide?', '["Yes, using the same coefficient it applies to carbon dioxide, since the coefficient is a property of the total pressure rather than of the molecule.", "Yes, but only above the cap, where the correction is held flat for both gases at the value the coefficient takes there.", "No, and it says so in a field rather than leaving the absence to be inferred, so `ph2sFugacityApplied` comes back false on every screening.", "No, and the absence is left undeclared, which is why a caller looking for the coefficient field has to work out from the results that none exists."]'::jsonb, 2, 'The hydrogen sulphide partial pressure at the shipped defaults is 0.051000 bar, printed as 0.739699 psia, and it is the total pressure times the mole fraction with nothing else done to it.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 13, 'What does the declared absence of a hydrogen sulphide fugacity correction let you say, and what does it not?', '["You may say a corrected pressure would sit lower, since the coefficient falls below one, and you may not say by how much without the constants.", "You may say the comparison is made on an uncorrected partial pressure. You may not say where a corrected one would land, because nothing here computes one.", "You may say both gases are treated alike, and you may not say which of the two the threshold comparison is made against.", "You may say the correction was withdrawn like the severity region, and you may not say whether it will return."]'::jsonb, 1, 'Whether a correction belongs there is a question for the literature and for the Fluid Properties course, which owns fugacity as a thermodynamic quantity. Here the honest statement is the narrow one.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 14, 'The ratio that decides which corrosion product governs is reported as 0.033333333333 on the shipped case. What is it free of?', '["Any held constant, which is why the regime word it produces is one of the few verdicts this course is able to grade.", "Any mole fraction, since the engine forms it from the two partial pressures the screening has already computed.", "Any dependence on the two mole fractions, since the engine forms it from partial pressures rather than from the composition itself.", "Any fugacity coefficient and any total pressure, because both of its arguments are partial pressures and the total pressure divides out."]'::jsonb, 3, 'Both arguments are the total pressure times a mole fraction, so the ratio equals the ratio of the two mole fractions at any pressure at all. The shipped fractions are 0.030000 and 0.001000.'),
  ('corrosion', 'beginner', 'module', 'm02-what-is-in-the-stream', 15, 'Where does the thermodynamics of fugacity belong, and what is this course''s own ground?', '["The Fluid Properties course owns the thermodynamics. What is specific here is the routing of the two quantities.", "This course owns both, since no other live course computes a fugacity coefficient from a temperature and a pressure.", "The Pipeline & Line Sizing course owns it, because the same coefficient appears in its own pressure drop calculation on the same stream.", "Neither, since the coefficient constants are held and a held quantity cannot be said to be owned by any course at all."]'::jsonb, 0, 'Name the owner for the thermodynamics, then teach which quantity drives the rate, which drives the threshold and the film ratio, and that no fugacity correction is applied to hydrogen sulphide at all.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 1, 'The engine computes a reaction term and a transport term and then combines them. What is the combination?', '["The smaller of the two terms, since a series chain can never run faster than its slowest step and the engine reports that step by name.", "The reciprocal of the sum of the two reciprocals, which is what putting two steps in series means.", "The product of the two terms divided by their difference, which is what keeps the answer below both of them at every ratio.", "The arithmetic mean of the two terms."]'::jsonb, 1, 'On the shipped case a reaction term of 44.225132 mm/yr and a transport term of 11.701938 mm/yr combine to 9.253475 mm/yr. Adding reciprocals is adding resistances.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 2, 'What can a learner say about the combined figure before seeing a single number?', '["It is below both terms, and it sits close to whichever of the two is the smaller.", "It is the smaller of the two terms whenever they differ by more than the reporting margin, and their mean whenever they do not.", "It is between the two terms, closer to the smaller one, which is what distinguishes a series combination from a simple minimum.", "It is above the smaller term whenever the two are comparable and below it whenever one dominates the other."]'::jsonb, 0, 'Adding two positive resistances gives a resistance larger than either, so the rate is smaller than either. The smaller term is the bottleneck and adding capacity to the faster step moves the answer very little.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 3, 'Four of the engine''s worked streams report the combined rate divided by the smaller of the two terms as 0.844077, 0.947776, 0.615743 and 0.990899. What does the spread show?', '["The ratio measures how far the controlling word is from its reporting margin, so a ratio near one means the engine is close to answering comparable.", "The ratio is the fraction of the rate that the reaction term contributes, so a stream at 0.990899 is almost entirely reaction controlled.", "The ratio rises with velocity on every stream, which is why the flow side of the model is the one that moves it.", "Where one term dominates the ratio approaches one, and where the two terms are comparable the combination falls well below both."]'::jsonb, 3, 'The stream at 0.990899 has a transport term of 0.091971 mm/yr against a reaction term of 10.013808 mm/yr. The stream at 0.615743 runs 44.114126 mm/yr against 70.689594 mm/yr, and its combination is 27.162967 mm/yr.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 4, 'One stream runs a reaction term of 44.114126 mm/yr against a transport term of 70.689594 mm/yr. What does the engine name as controlling, and what is the combination?', '["Mass transfer, with a combination of 27.162967 mm/yr, since the transport term is the larger figure and the larger figure is what the engine names.", "Comparable, with a combination of 27.162967 mm/yr, because the two terms sit inside the reporting margin of each other.", "Reaction kinetics, with a combination of 27.162967 mm/yr, because the reaction term is the smaller of the two here.", "Reaction kinetics, with a combination of 44.114126 mm/yr, since a series chain returns its slowest step unchanged."]'::jsonb, 2, 'This is the one stream of the six where the chemistry is slower than the transport. Its margin is 0.602425, which is the nearest of the six to the boundary at which the engine would answer comparable instead.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 5, 'The series identity is checked on every row the digest prints. What exactly is checked, and to what?', '["That the reciprocal of the combined rate minus the reciprocal of each term is zero, held to twelve figures.", "That the combined rate agrees with the vendored golden''s own combined rate to a tolerance of one part in a thousand on every case.", "That the combined rate lies between the smaller term and half of it, which is the band the identity allows on any positive pair.", "That the two terms agree with the constants the engine exports, measured by bisecting the rate at a fixed fugacity."]'::jsonb, 0, 'It is one of very few claims in this module that needs no held constant at all. Because it is arithmetic rather than a comparison against a fitted number, it survives whatever the correlation constants turn out to be.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 6, 'When the two terms sit within 10.000000 percent of each other, what does the engine report?', '["The smaller of the two by name, with a flag saying the choice was made inside the margin and should be read with care.", "Both terms by name in the order they were computed, leaving the reader to decide which of the two is doing the limiting.", "Nothing at all, so the controlling field is absent and the summary rail carries no row for it on those cases.", "Comparable, rather than naming either term, because a bare comparison of two nearly equal numbers flips on floating point noise."]'::jsonb, 3, 'The margin is a REPORTING threshold and the engine says so. It is not a claim about where mass transfer stops mattering physically, and it is measured out of the engine''s behaviour like every other constant here.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 7, 'Three streams report controlling margins of 2.779300, 0.602425 and 107.879479. How should those three be read?', '["As the ratio of the reaction term to the transport term, so a margin above one means the reaction term is the larger of the two.", "As the number of percentage points by which the controlling term leads the other, which is why the largest of the three is reported to six decimals.", "As how far each case sits from the boundary at which the engine would decline to name a term, so the smallest of the three is the least settled.", "As the fraction of the combined rate the controlling term accounts for, which is why the figures cluster near one on most streams."]'::jsonb, 2, 'The shipped case reports 2.779300 with transport controlling. A stream at 0.602425 sits much nearer the boundary, and one at 107.879479 is in no doubt at all.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 8, 'At a line inside diameter of 0.050800 m the transport term is 6.669367 mm/yr at 1 m/s, 11.612042 mm/yr at 2 m/s and 20.217739 mm/yr at 4 m/s. What do the two doubling ratios show?', '["They differ, and the difference between them is what the measured velocity exponent is derived from.", "Both come to 1.741101126592, and the same figure appears at every diameter in the sweep, which is what a power law in velocity means.", "Both come to 1.741101126592 at this diameter and to a different constant at each of the other three diameters, which is the diameter exponent showing through.", "Both come to 2.000000 because the term is linear in velocity, and 1.741101126592 is the ratio the diameter doubling gives instead."]'::jsonb, 1, 'At 0.101600 m the term is 5.806021 mm/yr, 10.108870 mm/yr and 17.600564 mm/yr, and the ratio is 1.741101126592 again. At 0.203200 m and 0.406400 m it is the same number once more.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 9, 'Why is a constant ratio down that column worth more to this course than an agreement to six decimals against an expected number?', '["It is measured at four diameters rather than one, so it carries four times the evidence a single comparison would carry.", "It is the only quantity in the transport term the engine exports, so it is the only one an export and a measurement can be compared on.", "It is scale free, so it tests the form of the term rather than the size of its constants, and it needs no expected number at all.", "It is computed by the oracle through an independent route, which is what makes it a validation rather than a pin."]'::jsonb, 2, 'An expected number produced by anything that shares a constant with the engine cannot test that constant. That is why this course leans on properties of this kind wherever it can find them.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 10, 'What are the two measured exponents of the transport term, and which way does each act?', '["0.800000000000 on velocity, which raises the term, and 0.200000000000 on diameter, which enters the other way round.", "0.800000000000 on diameter and 0.200000000000 on velocity, so line size is the stronger of the two levers on a line already in the ground.", "0.580000000000 on velocity and 0.200000000000 on diameter, the first being the exponent the reaction term shares with it.", "1.000000000000 on velocity and 1.000000000000 on diameter, since the term is exactly linear in both and only in the fugacity is it a power law."]'::jsonb, 0, 'The term is exactly linear in the carbon dioxide fugacity, which is a property rather than a typed constant. Both exponents and the coefficient in front of them are held for literature.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 11, 'The transport door is given a blank velocity. What does it return?', '["Zero, which propagates through the series combination and makes the combined rate zero as well.", "Not a number, and the vendored gate asserts the result is not infinity rather than merely checking it is not an ordinary number.", "Infinity, which is the honest limit of a transport term as the velocity supplied to it is taken down towards nothing at all.", "The last velocity the door happened to be called with, which is the reason a sweep over candidate line sizes has to be run in a fresh call for every one of them."]'::jsonb, 1, 'A blank diameter, a zero velocity and a negative diameter all behave the same way. A test that accepted any non finite value would pass on the behaviour this gate is written to prevent.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 12, 'Why would an infinite transport term be worse than a refusal?', '["It makes the combined rate infinite, which the studio would print as an unbounded rate and a remaining life of zero years.", "It moves the controlling margin past its reporting threshold, so the engine would answer comparable on every case with a missing velocity.", "It would be clamped to the largest finite double, which is a number a reader has no way of recognising as a failure.", "It makes the series combination equal the reaction term exactly, so the engine would name reaction kinetics as controlling from an input nobody supplied."]'::jsonb, 3, 'Every one of those outputs would look like an answer. The shape to look for in any engine is a function that hands back infinity, zero or one where it ought to hand back nothing.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 13, 'The rate door, `corrosionRate`, goes further than the bare transport door. What does it do with a blank velocity?', '["It returns a rate with the transport term omitted from the series combination and records the omission in the notes.", "It returns not a number in the rate field and leaves the rest of the screening intact, so the reader sees which fields survived.", "It refuses outright and names the box, in the engine''s own words that a positive velocity is required and an absent velocity is not an unlimited mass-transfer capacity.", "It substitutes the velocity from the previous call, which is why the studio clears every field between runs."]'::jsonb, 2, 'The bare term hands back a value a direct caller has to check, and the rate door refuses and names the input. The whole screening refuses earlier still, at the wall shear it computes first, saying the film survival check did not run.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 14, 'On the shipped case the transport term of 11.701938 mm/yr sits below the reaction term of 44.225132 mm/yr. What does the engine name, and what follows for the reader?', '["Mass transfer, so velocity and line size move this answer and the chemistry does not.", "Mass transfer, so temperature and carbon dioxide move this answer and the flow has already been accounted for.", "Reaction kinetics, because the reaction term is the larger figure and the larger figure sets the ceiling the rate is measured against.", "Comparable, because the two terms are within the reporting margin of each other at this velocity and diameter."]'::jsonb, 0, 'The word tells you which lever this model responds to. Where transport controls, velocity and line size change the answer. Where the reaction controls, temperature and carbon dioxide change it.'),
  ('corrosion', 'beginner', 'module', 'm03-two-resistances-in-series', 15, 'What is the safe reading of the controlling word, and what would be over reading it?', '["It says which of the two terms the reader should quote when a single number is asked for, and it is not a statement about the other term.", "It says which term the rate is nearer to in size, and it is not a statement about which input would move it.", "It says whether the correlation applies at all, and it is not a statement about which mechanism is faster.", "It says which lever this model responds to. It is not a verdict on the line, and two streams naming the same word can differ by a large factor in the rate."]'::jsonb, 3, 'A screening naming reaction kinetics on a stream near the comparable boundary would name something else after a small change in velocity. Record the word, the margin and the two terms together.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 1, 'Why does a naive extrapolation of the low temperature equation get a hot line backwards?', '["The reaction term saturates at high temperature, so the rate flattens rather than turning, and an extrapolation reads that flat stretch as a rise.", "The transport term overtakes the reaction term as the viscosity falls with temperature, so the series combination stops responding to the chemistry at all.", "Iron carbonate plates out on the steel above a certain temperature and the layer it forms slows the attack, so the rate turns and falls with further heating.", "The fugacity coefficient falls with temperature, so the fugacity the correlation is fed drops away faster than the temperature term can raise the rate."]'::jsonb, 2, 'The engine handles the turn with a multiplier on the rate. Below a computed onset it is exactly one, and above the onset it falls fast enough to take the rate downward.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 2, 'The film multiplier is clamped at one. What does the clamp state?', '["A direction rather than a magnitude, since a film can slow the attack and can never speed it up.", "A magnitude rather than a direction, since the clamp fixes how much of the rate the film is allowed to remove on any stream.", "The published validity band of the scale expression.", "The boundary the engine bisects to find the onset."]'::jsonb, 0, 'Applying the same expression with no ceiling would let a correction meant to be protective increase a rate instead. Below the onset the engine returns 1.000000000000 and the rate passes through untouched.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 3, 'What decides the temperature at which the multiplier leaves one?', '["The total pressure, which is why the onset sits beside the cap flag.", "The wetting regime, since a film forms only on a wall the water reaches.", "The reaction constants, which fix one onset for every stream.", "The carbon dioxide fugacity, from which the engine computes the onset rather than quoting a fixed figure."]'::jsonb, 3, 'The computed onset is teachable because it is measured out of the engine''s own behaviour by bisection and cross checked against a closed form. What the published correlation turns at is a separate question and it is held.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 4, 'The digest sweeps the onset across seven carbon dioxide fugacities. What do those figures show?', '["It rises as the fugacity rises, from 35.853960 C at 0.050000 bar to 132.297731 C at 60.000000 bar, which is why a high pressure line credits no film.", "It falls as the fugacity rises, from 132.297731 C at 0.050000 bar to 35.853960 C at 60.000000 bar.", "It holds near 85.058955 C across the whole sweep and moves only when the temperature itself is changed.", "It falls to a floor at 35.853960 C and is clamped there, in the same way the fugacity coefficient is clamped above its own cap."]'::jsonb, 1, 'At 0.200000 bar the onset is 108.978001 C, at 1.000000 bar 85.058955 C, at 2.000000 bar 75.655878 C, at 5.000000 bar 63.957912 C and at 20.000000 bar 47.679108 C.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 5, 'Across the fugacities the digest sweeps, how far does the onset move?', '["Nothing measurable, because the onset is a constant of the scale expression and the sweep is there to demonstrate that it does not move.", "10.000000 percent, the engine''s own reporting margin.", "96.443771 degrees Celsius, which is what retires the idea of a single film onset temperature.", "80.984504 degrees Celsius, which is the onset the engine computes at the shipped studio defaults and also the width of the swept band."]'::jsonb, 2, 'A help guide saying the film appears at a round temperature is wrong at every fugacity except one. The panel prints the computed onset for the conditions set rather than a constant.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 6, 'At the shipped studio defaults the carbon dioxide fugacity is 1.344240 bar. What is the onset there, and what is the multiplier?', '["An onset of 80.984504 C, and a multiplier of exactly 1.000000000000 because the stream runs at 60.000000 C.", "An onset of 80.984504 C, and a multiplier of 0.206012 because the stream is credited with a partial film at that fugacity.", "An onset of 85.058955 C, and a multiplier of exactly one, since the onset at a fugacity near 1.000000 bar is what the shipped case is closest to.", "An onset of 60.000000 C, and a multiplier just below one."]'::jsonb, 0, 'No film credit is taken on that screen at all. Every capstone scenario in this course is deliberately below its own computed onset for the same reason.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 7, 'Two of the engine''s worked streams sit on opposite sides of their own onsets. What are the two answers?', '["Both have multipliers below one, and the difference between the two is only how far below, which the onset figure records.", "One at 119.400000 C with an onset of 79.792274 C has a multiplier of 0.206012, and one at 58.200000 C with an onset of 89.053653 C has a multiplier of exactly one.", "One has an onset of 79.792274 C and the other of 89.053653 C, and both credit a film because both onsets sit below the temperature of the shipped case.", "One is above its onset and refuses a rate, and the other is below its onset and returns one, which is the refusal the scale door owns."]'::jsonb, 1, 'The first runs at a fugacity of 1.467680 bar and the second at 0.753085 bar. One expression, two streams, two different answers about whether a film exists at all.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 8, 'Hold the composition fixed and walk the temperature up one of the engine''s streams. What does the rate column do?', '["It rises without turning across the whole walk, and only the multiplier column turns, which is why the two have to be read together.", "It falls throughout the walk, because the film is credited from the first step.", "It holds flat until the onset and then falls away.", "It rises to 1.508421 mm/yr at 70.000000 C, then turns and falls away, reaching 0.135116 mm/yr at 150.000000 C."]'::jsonb, 3, 'At 40.000000 C the rate is 1.270135 mm/yr and at 55.000000 C it is 1.401052 mm/yr, both with a multiplier of exactly one. The turn is the film arriving rather than the chemistry slowing.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 9, 'On that same walk, at which step is the film first credited and what is the multiplier there?', '["At 70.000000 C, with a multiplier of 0.435371430361, which is the step at which the rate stops rising.", "At 100.000000 C, with a multiplier of 0.242520118987, which is the first step at which the rate falls below its value at the start of the walk.", "At 85.000000 C, with a multiplier of 0.820838044032.", "At 40.000000 C, with a multiplier of 1.000000000000, since a multiplier is credited at every step and only its size changes."]'::jsonb, 2, 'At 100.000000 C the multiplier is 0.435371430361 and the rate is 0.728051 mm/yr. At 130.000000 C it is 0.141105882050 and the rate is 0.252905 mm/yr.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 10, 'Of the six worked streams in this course''s source material, how many carry a film multiplier of exactly one?', '["1 of the 6, which is the shipped studio case, and the other five are all above their own computed onsets.", "5 of the 6, so no film credit is in their rates at all.", "3 of the 6, which is the split that makes the sweep a fair test of both sides of the onset.", "All 6, since every scenario used anywhere in this course is set below its own onset by construction."]'::jsonb, 1, 'The shipped studio case, which is not one of the six, sits below its onset too, at 60.000000 C with a computed onset of 80.984504 C. Where the multiplier is exactly one, multiplying by it changes nothing at all.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 11, 'Where in the chain does this engine apply the film multiplier, and what is the standing of that choice?', '["It multiplies the combined rate after the series combination, and which form the published correlation intends is held.", "It multiplies the reaction term before the series combination.", "It multiplies the transport term, since a film is a barrier to transport.", "It applies the multiplier once to each of the two terms."]'::jsonb, 0, 'Multiplying the reaction term instead is a different physical claim. The two give materially different answers whenever mass transfer controls, which it does at the studio''s own defaults.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 12, 'What follows for this course from that unresolved modelling question?', '["The factor is graded only on streams where the reaction term is the smaller of the two, because the two arrangements agree there.", "The factor is graded at the Expert tier alone, where a learner is expected to state which arrangement the engine uses before quoting a rate.", "The rate is graded and the factor is not, since the factor is a multiplier the learner never has to produce on its own.", "Nothing downstream of the film factor is graded anywhere in these three tiers."]'::jsonb, 3, 'A rate carrying a film credit depends on an unresolved modelling decision as well as on three unsourced constants, so grading one would examine a learner on a question the engine itself declines to settle.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 13, 'Every capstone scenario in this course sits below its own computed onset. Why does that clear the arrangement question?', '["The multiplier is then small enough that the difference between the two arrangements falls inside the grading tolerance on every field.", "The scale constants drop out of the chain below the onset, so the rate is reached without any held constant at all.", "The multiplier is then exactly one, and multiplying by one before the combination or after it gives the same number to the last bit.", "The engine refuses to apply the factor below the onset, so a scenario there is graded on a chain the factor never entered."]'::jsonb, 2, 'It is an identity rather than a tolerance, which is why it is worth stating as the reason. The capstone generator asserts it rather than assuming it.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 14, 'Which of these is held for literature in the film part of this module?', '["The clamp at one, which is the one part of the correction carrying no source anywhere in this repository and is therefore never graded.", "The three constants of the scale expression and the temperature at which the published correlation turns protective.", "The computed onset, which is the reason the engine declines to print it and shows only the multiplier beside the rate on the screen.", "The direction of the correction, since no source in the repository says whether a film raises or lowers the rate."]'::jsonb, 1, 'The published turning temperature is a separate question from the onset this engine computes. The clamp itself is arithmetic and it is not held.'),
  ('corrosion', 'beginner', 'module', 'm04-the-protective-film', 15, 'A screening from a hot line reports a reassuringly low rate. What should the reader record beside it?', '["The multiplier, whenever it is below one, so the next reader can see how much of the answer the film credit is carrying.", "The reaction term on its own, since that is the figure the rate would have taken had the film not been credited at those conditions.", "The published onset temperature for the correlation.", "The wall shear, since a film credited by the correlation is only removed when the shear exceeds the erosional velocity limit this module carries."]'::jsonb, 0, 'A rate that looks low at high temperature is carrying a film credit inside it, and that credit rests on constants nobody here can source. The module holds no erosional velocity criterion at all.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 1, 'The pH correction is a multiplier relative to something. Relative to what, and what is it there?', '["Relative to neutral water, so the factor is exactly one at a pH of seven and departs from one on either side of it.", "Relative to the pH the correlation was fitted at, which is 4.000000, where the factor is exactly 1.000000.", "Relative to the in situ pH of the shipped case, 4.500000.", "Relative to whichever pH the previous run happened to use."]'::jsonb, 1, 'The engine returns the reference with the factor, so a reader always knows what the correction is taken against. At the reference the factor is one by definition rather than by a clamp.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 2, 'Read the factors down the swept column. What are they?', '["1.000000 at a pH of 9.000000 and 0.003162 at 4.000000, so the correction rises as the water becomes more acid across the band.", "0.562341 at 4.000000 and 1.000000 at 4.500000, which is the shipped in situ pH and the condition the correction is taken against.", "1.000000 at every pH in the band, since the correction never reaches the rate.", "1.000000 at a pH of 4.000000, 0.316228 at 5.000000, 0.100000 at 6.000000, 0.031623 at 7.000000 and 0.010000 at 8.000000."]'::jsonb, 3, 'At 4.500000 the factor is 0.562341 and at 5.500000 it is 0.177828, so the half unit steps fill the same pattern in. Above the reference the factor falls below one, which reduces the rate.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 3, 'What is the scale free property of the pH correction, and what did the digest measure for it?', '["One decade per pH unit, and the measured ratio came out at 0.100000000000 at every step of the swept band.", "A halving per pH unit, and the measured ratio came out at 0.562341 four times, which is the factor at the shipped in situ pH.", "One decade per two pH units, and the measured ratio came out at 0.100000000000 four times across the swept band.", "A fixed difference rather than a fixed ratio, and the measured step came out at 0.100000000000 across the band."]'::jsonb, 2, 'Every one of the four is the same number. It is a property of the FORM of the correction rather than of the size of its slope, so it can be checked from the outside on any machine.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 4, 'On one of the engine''s worked streams the rate falls from 4.724817 mm/yr at a pH of 4.000000 to 0.014941 mm/yr at 9.000000. What is the ratio between the two ends?', '["316.227766.", "100.000000, which is the two decades the correction covers across a five unit walk in pH.", "0.100000000000, which is the same figure the two unit decade property is measured at.", "1.741101126592, which is the ratio a doubling produces anywhere in this engine."]'::jsonb, 0, 'The rate falls at every step of that column and each step down is smaller than the one above it. The generator asserts that on every rebuild rather than printing it once and trusting it.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 5, 'The decade ratio is measured out of the engine rather than compared against a figure prepared in advance. Why does this course prefer that?', '["A scale free property can be measured at more points, so it carries more evidence than a single comparison against one expected figure.", "A scale free property is what the engine exports, so it is the only quantity on which a declaration and a behaviour can be compared.", "An expected number has to be rounded before it can be compared, and rounding is what the precision rules in this course exist to prevent.", "An expected number produced by anything sharing a constant with the engine cannot test that constant, and a scale free ratio needs no expected number at all."]'::jsonb, 3, 'The decade property tells you the correction is a clean power law and it tells you nothing about whether the power is the published one. The slope itself is held for literature.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 6, 'Set an in situ pH of 3.500000 on a screening. What comes back?', '["A refusal, carrying the reference of 4.000000 so a caller can print the boundary to the user.", "A factor of 1.000000000000, which is the boundary value the correction is clamped to below its own reference.", "A factor extrapolated from the slope and marked as such.", "A refusal from the range guard of nought to fourteen."]'::jsonb, 0, 'The same answer comes back at 2.000000, at 3.000000 and at 3.999900. At exactly 4.000000 the engine returns a factor of 1.000000000000, which is the boundary reached by definition.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 7, 'The engine''s refusal below the reference says what, in its own words?', '["That the in situ pH is outside the band the correction was fitted over, and that the nearest value inside the band has been used instead.", "That a more acid water is a more corrosive one, and that the correction has therefore been clamped to its largest permitted value.", "That the pH correction is only defined at or above its reference pH of 4, that pH 3.5 is below it, and that no factor is returned rather than a factor of 1.", "That the screening is incomplete because the pH correction did not run, in the same words the shear refusal uses."]'::jsonb, 2, 'The message names the reference so the reader is left in no doubt that the model has run out of ground. A refusal travels well, and it reaches a colleague reading the screenshot a week later.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 8, 'Why would a factor of one below the reference be the wrong silence?', '["It is the most limiting answer available, so it would report a rate above anything the correlation could support at that acidity.", "It is the least limiting answer available, and it would make an input inert across a whole range while the box still accepted values.", "It would break the one decade per two pH units property, which is asserted across the whole swept band and would fail on the first rebuild of the digest.", "It would disagree with the boundary value the engine returns at exactly 4.000000, where a factor above one is what the correction gives instead."]'::jsonb, 1, 'A more acid water is not a less corrosive one. Refusing puts the limit where the user can see it and forces the next decision to be made by a person with a reason instead of by a default.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 9, 'The reference guard and the range guard are separate. What does each one do?', '["The range guard enforces the published validity band of the correlation and the reference guard enforces the band the studio accepts in its own box.", "The range guard runs on the whole screening door and the reference guard runs on the bare factor door, so only one of them is reachable from the studio.", "The range guard enforces a pH between nought and fourteen and names the value typed. The reference guard sits inside that range and refuses a chemically valid pH.", "The range guard refuses and the reference guard clamps, which is why a pH below 4.000000 still produces a number while a pH of 15 does not."]'::jsonb, 2, 'A pH of 15 comes back as an in-situ pH between 0 and 14 is required. A blank box is refused by a third message again, because a blank is a question rather than a value.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 10, 'The shipped case runs at an in situ pH of 4.500000. Move it to 4.000000 and what happens to the rate?', '["It rises from 0.754524 mm/yr to 1.341754 mm/yr, and below 4.000000 the engine refuses.", "It falls from 1.341754 mm/yr to 0.754524 mm/yr, since the correction reduces the rate as the water becomes more acid.", "It stays at 0.754524 mm/yr, since the pH correction reaches the reported rate only through the wetting regime.", "It rises from 0.754524 mm/yr to 4.724817 mm/yr, which is the rate the correlation gives at its own fitted condition."]'::jsonb, 0, 'A learner should be able to say why those two facts belong together. The pH factor at 4.500000 is 0.562341, and at the reference it is exactly one.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 11, 'Change the in situ pH box alone on the shipped case. Which other factor in the chain moves?', '["The film multiplier moves with it, because the onset expression takes the pH factor as one of its arguments.", "The wetting factor moves with it, because both corrections are applied to the same combined figure in the same step.", "The transport term moves with it, because the pH reaches the rate through the water chemistry at the wall.", "None of the others, which is what makes a change in the printed rate easy to attribute to a cause."]'::jsonb, 3, 'The pH factor is one of the multipliers applied to the combined figure the two rate terms produce, alongside the film multiplier, the wetting regime and the corrosion inhibitor credit.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 12, 'What does in situ pH mean on that box, and why does the distinction matter?', '["The pH of the produced water at the surface separator, which is the measurement most operators on a live system already have to hand.", "Hydrogen ion activity in the water phase at conditions, which is not a produced water sample measured at the surface.", "The pH the correlation itself was fitted at, which is the reason the box on the studio ships already filled in at a value near the reference.", "The pH of the condensed water alone, which is what a top of line calculation would need and this module returns."]'::jsonb, 1, 'The difference between the two numbers on a live system is not small. The box on the screen asks for the in situ value and the correction is taken against the fitted condition.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 13, 'Take the shipped case and choose oil wet instead of water wet. What happens to the rate and to the two fields beside it?', '["The rate becomes 0.000000 mm/yr, the category reads negligible and the remaining life is reported as unbounded.", "The rate is unchanged, because the wetting regime reaches only the summary and not the calculation behind it.", "The rate becomes 0.000000 mm/yr, and both the category and the remaining life are withheld.", "The rate becomes 0.000000 mm/yr and the screening refuses, since a zero rate cannot be divided into an allowance."]'::jsonb, 2, 'The binding constraint on that case reads that the model does not apply. The rate is zero because oil wetting was assumed rather than because a rate was calculated.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 14, 'On that oil wet case the corrosion inhibition figure comes back as null rather than as zero. Why?', '["Zero is reserved for a programme that was typed in at zero efficiency, so null is what the engine uses for every other absent figure.", "The corrosion inhibitor arithmetic is the one part of the chain that refuses rather than returning, so null is what a refusal looks like in that field.", "Null is what the field carries whenever the rate is withheld, which is the same treatment the category and the life receive.", "A reported zero percent effectiveness on a line that has a corrosion inhibitor programme would be a statement, and it would be a false one."]'::jsonb, 3, 'There is nothing for the programme to be effective against when the rate is zero by assumption. An unbounded life arriving off a dropdown would be the strongest reassurance on the screen resting on the weakest input in it.'),
  ('corrosion', 'beginner', 'module', 'm05-ph-and-the-water', 15, 'How should the wetting dropdown be treated by the person setting it?', '["As an assertion being made about the whole line at all times, including start up, shutdown, low rate operation and any low point where water can collect.", "As a setting chosen from the water cut, since the engine reads the water cut fraction in every one of the three regimes.", "As a reporting preference, since the regime reaches the summary rail and the rate is computed the same way whichever is chosen.", "As a value the engine will correct, since an unrecognised regime falls through to the least limiting of the three."]'::jsonb, 0, 'An unrecognised string is refused and the message lists the three regimes the engine accepts, so a typed regime never falls through. If the claim cannot be defended, the intermittent regime exists.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 1, 'The studio''s shipped case types a temperature of 140 F, a pressure of 725 psig and a velocity of 10 ft/s. What reaches the engine?', '["60.000000 C, 725 bar and 3.048000 m/s, since the pressure is the one field the engine takes in the unit it was typed in.", "60.000000 C, 51.000427 bar and 3.048000 m/s.", "140 C, 51.000427 bar and 10.000000 m/s, since only the pressure carries a conversion on the way in.", "60.000000 C, 51.000427 bar and 0.152400 m/s, the velocity being converted by the same factor as the line inside diameter."]'::jsonb, 1, 'The engine works in the units the correlations are published in. A line inside diameter of 6 in becomes 0.152400 m, a density of 56 lb/ft3 becomes 897.036000 kg/m3 and a viscosity of 1 cp becomes 1.000000 mPa s.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 2, 'On the shipped case a reaction term of 44.225132 mm/yr and a transport term of 11.701938 mm/yr are handed to the step that combines them. What comes out, and which step is named?', '["A combined figure of 27.162967 mm/yr, which is the two terms in series, with transport controlling.", "A combined figure of 11.701938 mm/yr, the smaller term unchanged.", "A combined figure of 9.253475 mm/yr with reaction kinetics controlling, since the reaction term is the larger of the two.", "A combined figure of 9.253475 mm/yr with transport controlling at a margin of 2.779300."]'::jsonb, 3, 'The combination is the reciprocal of the sum of the reciprocals, so it sits below both terms and near the smaller one. Where transport controls, velocity and line size move the answer.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 3, 'Between the combined figure of 9.253475 mm/yr and the uninhibited rate of 5.203611 mm/yr, what has been applied?', '["The film multiplier of 1.000000000000, the pH factor of 0.562341 and the water wetting factor of 1.000000.", "The corrosion inhibitor credit of 85.500000 percent.", "The conversion from mm/yr to mpy and back again.", "The fugacity coefficient of 0.878581, applied to the combined figure."]'::jsonb, 0, 'The computed film onset is 80.984504 C and the stream is at 60.000000 C, so no film credit is taken. The uninhibited rate is the same case with no corrosion inhibitor credit at all.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 4, 'The datasheet corrosion inhibitor is 90.000000 percent efficient at 95.000000 percent availability. What does the engine report, and what is the rate?', '["An effective protection of 90.000000 percent and a rate of 0.754524 mm/yr, the availability being reported beside it without entering the arithmetic.", "An effective protection of 95.000000 percent and a rate of 5.203611 mm/yr.", "An effective protection of 85.500000 percent, a shortfall of 4.500000 percentage points, and a rate of 0.754524 mm/yr.", "An effective protection of 85.500000 percent and a rate of 5.203611 mm/yr."]'::jsonb, 2, 'The engine''s warning on that screen names availability as what limits the result, and it states the metal loss as 1.45 times the datasheet number. The uninhibited rate is 5.203611 mm/yr.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 5, 'Every rate on the shipped screen carries mpy beside mm/yr. What are the two figures for the reported rate and for the uninhibited rate?', '["0.754524 mm/yr is 204.866591 mpy, and 5.203611 mm/yr is 29.705656 mpy, the two being reported in the opposite order on the rail.", "0.754524 mm/yr is 29.705656 mpy, and 5.203611 mm/yr is 204.866591 mpy.", "0.754524 mm/yr is 29.705656 mpy, and the uninhibited rate is reported in mm/yr alone because no datasheet figure exists for it.", "Both convert to the same mpy figure of 29.705656, since the conversion is applied once to the reported rate and carried across."]'::jsonb, 1, 'The conversion is a division by 25.4 and a multiplication by a thousand, and it is stated rather than assumed. The reaction term of 44.225132 mm/yr is 1741.146915 mpy.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 6, 'What does the flow side of the shipped screen report?', '["A Reynolds number of 416686.8569 and a wall shear of 362.474888 Pa, with the film risk high and the corrosion inhibitor credit removed.", "A Reynolds number of 416686.8569 with the laminar branch selected, since the switch sits at a Reynolds number of 4000.000000.", "A wall shear of 14.408065 Pa with no Reynolds number, since this module reads the friction factor from the line sizing course instead.", "A Reynolds number of 416686.8569 on this module''s own definition, a turbulent branch, a wall shear of 14.408065 Pa and a film risk of low."]'::jsonb, 3, 'So no corrosion inhibitor credit is removed on this screen. The Pipeline & Line Sizing course computes its own friction factor and its own Reynolds number with a different correlation, and the two will not agree on the same pipe.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 7, 'Read the hydrogen sulphide rows on that same default case. What is on them?', '["A hydrogen sulphide partial pressure of 0.051000 bar, which is 0.739699 psia, above the screening threshold by 1.163506 decades.", "A hydrogen sulphide partial pressure of 0.051000 bar, below the screening threshold, with the severity region reported as low.", "A hydrogen sulphide fugacity of 0.051000 bar, above the screening threshold, with a material recommendation the studio prints behind a disclosure.", "A hydrogen sulphide partial pressure of 1.530013 bar, above the screening threshold by 1.163506 decades, with the region held rather than withdrawn."]'::jsonb, 0, 'The severity region and the material guidance are both reported as NOT PROVIDED. The comparison is made on an uncorrected partial pressure, and the threshold value itself is held.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 8, 'The shipped screen reports a hydrogen sulphide to carbon dioxide ratio of 0.033333333333. What regime does that give, and what does the engine say about the rate?', '["Carbonate, and the rate is graded normally with no marking of any kind on it.", "Sulphide, and the rate is withheld along with the category and the remaining life.", "Mixed, and the rate is marked as an upper bound.", "Mixed, and the rate is withheld because a mixed film means the model no longer describes the surface."]'::jsonb, 2, 'A mixed film is not a reason to withhold a screening number, only a reason to read it as a ceiling. The ratio equals the ratio of the two mole fractions, which here are 0.030000 and 0.001000.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 9, 'The allowance block on the shipped screen reads what?', '["A remaining allowance of 3.175000 mm, a remaining life of 20.000000 yr and no shortfall, since nothing has been consumed on this case.", "A remaining allowance of 3.175000 mm, a remaining life of 4.207953 yr, an allowance the design life demands of 15.090473 mm and a shortfall of 11.915473 mm.", "A remaining allowance of 15.090473 mm and a remaining life of 4.207953 yr, the first being what the design life demands and the second what the rate gives.", "A remaining allowance of 3.175000 mm and a remaining life of 4.207953 yr, with no demanded allowance because no design life was supplied."]'::jsonb, 1, 'The case does not meet its design life of 20.000000 yr. The consumed depth on the shipped case is 0.000000 mm, so the remaining allowance is the whole 3.175000 mm.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 10, 'The binding constraint on the shipped screen is the corrosion allowance against the design life. What does the engine say it turns on?', '["4.2 yr of 20 yr, and the sentence beside it names the allowance shortfall in millimetres.", "14.408065 Pa of wall shear, which is the value the shear branch of the reconciliation reads.", "0.033333333333, the ratio the regime branch reads.", "2.779300, the controlling margin on that case."]'::jsonb, 0, 'In the engine''s own words: at 0.755 mm/yr the allowance runs out in 4.2 years against a 20 year design life, short by 11.92 mm of allowance. Nothing in that sentence is new information.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 11, 'Take the velocity from 10 to 60 ft/s on the shipped case. What happens?', '["The wall shear becomes 362.474888 Pa and the rate is unchanged, since the shear reaches the summary rail and not the calculation.", "The rate falls, because a higher velocity raises the transport term and the series combination sits nearer the smaller term.", "The screening refuses, because a velocity of that size is outside the published validity band of the transport correlation.", "The wall shear becomes 362.474888 Pa against the measured stripping threshold of 100.000000 Pa, the corrosion inhibitor credit is removed, and the rate becomes 13.080024 mm/yr."]'::jsonb, 3, 'The credited rate of 1.896603 mm/yr is reported beside it, so the cost of the shear verdict is visible. The binding constraint becomes the wall shear on the corrosion inhibitor film.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 12, 'One change moves the hydrogen sulphide box from 0.1 to 1 mol%. Where does the reported rate end up?', '["It rises, because the ratio of 0.333333333333 puts the stream in the sulphide regime, where the sulphide film is the faster of the two mechanisms competing at the wall.", "It falls, by the ratio of the two partial pressures.", "It is unchanged at 0.754524 mm/yr, because hydrogen sulphide is not in the correlation at all.", "It is withheld along with the category and the life, so no rate figure is reported on that screening at all."]'::jsonb, 2, 'What changes is that the category and the remaining life are withheld and the rate is kept only as a stated upper bound. The regime becomes sulphide and the binding constraint becomes that the model does not apply.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 13, 'Two of the five changes to the shipped case end with the same binding constraint. Which two, and what is it?', '["The move to 60 ft/s and the move to 1 mol% hydrogen sulphide, and the constraint is the wall shear on the corrosion inhibitor film.", "The move to 1 mol% hydrogen sulphide and the move to the oil wet regime, and the constraint is that the model does not apply.", "The move to pH 4.0 and the move to the oil wet regime, and the constraint is the allowance against the design life.", "The move to 60 ft/s and the move to pH 4.0, and the constraint is mass transfer to the wall."]'::jsonb, 1, 'Both of those two cases withhold the category and the remaining life, so no rate verdict is being offered and the reader is sent to the withheld block instead.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 14, 'The shipped screen prints the two rate terms in mils a year as well as in millimetres a year. What are those two figures?', '["1741.146915 mpy for the reaction term and 460.706213 mpy for the transport term.", "460.706213 mpy for the reaction term and 1741.146915 mpy for the transport term, in the order the rail prints them.", "29.705656 mpy and 204.866591 mpy, which are the two rates the corrosion inhibitor credit sits between.", "1741.146915 mpy for the reaction term, with the transport term printed in millimetres a year alone."]'::jsonb, 0, 'The two terms in millimetres a year are 44.225132 and 11.701938. Every rate on that screen carries mpy beside mm/yr, because every input on it is in field units.'),
  ('corrosion', 'beginner', 'module', 'm06-one-screen-end-to-end', 15, 'Why does the shipped screen name a limit at all rather than leaving the reader with its fields?', '["Because a binding constraint is required before a rate can be issued, which is why the screening is incomplete without one.", "Because the named limit is what the capstone grades.", "Because the limit is the one field carrying no held constant.", "A reader handed seven independent numbers and no reconciliation summarises by reading the largest one."]'::jsonb, 3, 'The named limit tells you what to change first. It is silent about what steel to buy, when to inspect and what thickness to retire at, because the module has none of those.'),
  ('corrosion', 'beginner', 'final', null, 1, 'One door in this engine takes a rate in millimetres a year and returns a band label. What else does it return?', '["A band label with the band edges beside it, so a reader can see which edge the rate fell on.", "A band label and a remaining life, since the two are the only fields the summary rail reconciles.", "Nothing else at all, and the label it returns rests on band edges that carry no source.", "A band label and a confidence figure derived from how far the rate sits from the nearest edge."]'::jsonb, 2, 'The band edges are held for literature, and the engine says in its own held list that they may be optimistic by one or two steps against the bands commonly cited for carbon steel in production service.'),
  ('corrosion', 'beginner', 'final', null, 2, 'What does the door that returns the temperature at which the film multiplier leaves one need in order to answer?', '["A carbon dioxide fugacity, and nothing besides.", "A temperature and a carbon dioxide fugacity, since an onset is reported relative to the stream it belongs to.", "A temperature, a velocity and a line inside diameter, because the onset is reached through the series combination.", "A total pressure and a carbon dioxide mole fraction, from which the door forms the fugacity it needs."]'::jsonb, 0, 'The onset moves with the fugacity alone, which is what makes it computed rather than quoted. At the shipped defaults the fugacity is 1.344240 bar and the onset is 80.984504 C.'),
  ('corrosion', 'beginner', 'final', null, 3, 'The vendored golden says in its own words that every row in it is synthetic. What reason does it give?', '["The rows were generated from the engine itself, so an agreement between the two is arithmetic rather than evidence.", "The published cases that do exist sit above the fugacity cap, where the engine reports a convention rather than a prediction.", "The rows are regenerated on every rebuild, so none of them predates the behaviour it is checking.", "No published case of the correlation, no clause of either sour service standard and no rate band table exists anywhere in the repository."]'::jsonb, 3, 'The golden adds that a number recalled from memory is not a published datum and that none is typed there. Route independence and the gate''s pins carry the load instead.'),
  ('corrosion', 'beginner', 'final', null, 4, 'A reader takes the single rate off this screen and plans an inspection around the worst spot on a line. What has gone wrong?', '["The rate is a localised rate, so it describes the worst spot and understates the loss spread over the rest of the wetted surface.", "The rate is an upper bound in every regime, so planning against it is conservative and the plan will be earlier than it needs to be.", "The rate is a general uniform rate, so it carries no geometry, no weld, no bend and no deposit and cannot say where the first leak will be.", "Nothing has gone wrong with the rate itself. The fault is that an inspection interval needs a design life, which this particular reader never supplied."]'::jsonb, 2, 'The engine states it in its own list of absences by naming a localised attack rate as something it does not provide. The module holds no localised model to compare a uniform rate against.'),
  ('corrosion', 'beginner', 'final', null, 5, 'Three Suite studios take a corrosion allowance and do not know about each other. What is the relationship between them?', '["This one consumes an allowance to give a life, and the other two add one to a wall, so the wall this studio eats is not the wall either of those sized.", "All three consume the same allowance from one shared record, which is why a change in any of them moves the remaining life reported here.", "This one adds an allowance to a pressure containing wall and the other two consume it, which is the reverse of what a reader usually assumes.", "All three add an allowance, so the three figures have to be summed before a minimum thickness can be reached."]'::jsonb, 0, 'There is no link between them and no minimum thickness anywhere. That is recorded, it is stated in the studio''s help, and it is deliberately not wired up, because a link between three apps is a design decision.'),
  ('corrosion', 'beginner', 'final', null, 6, 'The sour door prints its threshold in both units inside its own note. Why?', '["So the studio can show whichever unit the user chose.", "So the derived figure can be compared against the exported one, which is the pin that holds the threshold in place.", "So a caller can tell a held threshold from a sourced one, since only a held value is ever printed in two units.", "So nobody has to convert it, and so a reader can see which of the two numbers a comparison was made against."]'::jsonb, 3, 'The engine declares the value held through a field of its own. Its measured value is 0.003500000000 bar, which is 0.050763208303 psia, and it is bisected out of the sour flag rather than read.'),
  ('corrosion', 'beginner', 'final', null, 7, 'Two mole fractions are each inside nought to one and the engine still refuses. What has it checked?', '["The sum of the two against the water cut fraction, since the three together describe how the stream divides at the wall.", "The sum of the two against the total pressure, because two fractions inside their own range can still put the partial pressures above the total.", "Each fraction against the other, because the ratio between them has to fall inside the regime boundaries before a regime word can be issued.", "The sum of the two against the fugacity cap, because above the cap the coefficient is held and the sum can no longer be resolved."]'::jsonb, 1, 'The message names the sum it formed. A sum of exactly one is accepted, and the screening runs with a partial pressure sum of 51.000427 bar against a total of 51.000427 bar.'),
  ('corrosion', 'beginner', 'final', null, 8, 'At a total pressure of 100.000000 bar with the digest''s fixed composition, what are the three chemistry figures?', '["A coefficient of 0.775834, a partial pressure of 2.327502 bar and a fugacity of 3.000000 bar.", "A coefficient of 0.880814, a partial pressure of 3.000000 bar and a fugacity of 2.327502 bar.", "A coefficient of 0.775834, a carbon dioxide partial pressure of 3.000000 bar and a fugacity of 2.327502 bar.", "A coefficient of 0.775834, a partial pressure of 3.000000 bar and a fugacity of 3.000000 bar, the cap having been applied."]'::jsonb, 2, 'At 200.000000 bar the same composition gives a coefficient of 0.601919, a partial pressure of 6.000000 bar and a fugacity of 3.611511 bar. The separation between the two quantities is a pressure effect.'),
  ('corrosion', 'beginner', 'final', null, 9, 'Run a screening at a total pressure of 251.000000 bar. What does the cap flag do, and what does the coefficient do?', '["The flag turns true and the coefficient holds at 0.530179, which is its value at the cap.", "The flag stays false until the pressure is well above the cap, and the coefficient falls on through 0.530179 as it would below it.", "The flag turns true and the coefficient is set to one, which is the least limiting value the correction can take.", "The flag turns true and the screening refuses, since nothing above the cap can be reported as a rate."]'::jsonb, 0, 'At 249.000000 bar the coefficient is 0.531526 and the flag is false. The cap is a reported limit rather than a silent one, and the engine returns a note saying what it is doing.'),
  ('corrosion', 'beginner', 'final', null, 10, 'At a total pressure of 1.000000 bar the fugacity coefficient is 0.997465. What does that tell a reader?', '["That the coefficient is clamped at one below a lower cap, in the same way it is held flat above the upper one.", "That the correlation was fitted at atmospheric pressure, so the coefficient is exactly one there by definition.", "That the two quantities can be used interchangeably at any pressure at all, since the correction never leaves the sixth decimal on any stream.", "That the gap between a partial pressure and a fugacity is negligible near atmospheric pressure and is not negligible on a high pressure line."]'::jsonb, 3, 'Here the fugacity is 0.029924 bar against a partial pressure of 0.030000 bar, and at 200.000000 bar it is 3.611511 bar against 6.000000 bar. The constants behind the coefficient are held for literature like the rest.'),
  ('corrosion', 'beginner', 'final', null, 11, 'Which set is made up entirely of range guards this module enforces on what a caller types, rather than published validity bands it holds?', '["The published validity band of each correlation, the fugacity cap, the pH reference and the film stripping threshold.", "Nought to one on every fraction, the fugacity pressure cap, the pH reference and a positive velocity on the transport term.", "Nought to one on every fraction, nought to fourteen on pH, a temperature above absolute zero, and the partial pressure sum against the total.", "A temperature above absolute zero, a positive total pressure, and the published validity band of the transport term on velocity and line size."]'::jsonb, 2, 'Every published validity band of every correlation is held, so a screening well outside one still returns a number and says nothing about it.'),
  ('corrosion', 'beginner', 'final', null, 12, 'Which quantity does the hydrogen sulphide screening comparison use, and how does the engine make that visible?', '["A corrected fugacity, and the engine makes it visible by reporting the coefficient it used beside the comparison.", "An uncorrected partial pressure, and the engine declares it by returning a flag saying no fugacity correction was applied.", "An uncorrected partial pressure, and the engine leaves it to the reader to notice that no coefficient field is returned.", "Whichever of the two the caller supplied, and the engine records the choice in the clamps list beside the other moved inputs."]'::jsonb, 1, 'The flag reads false on every case the engine ships. At the shipped defaults the hydrogen sulphide partial pressure is 0.051000 bar, printed as 0.739699 psia.'),
  ('corrosion', 'beginner', 'final', null, 13, 'A fugacity is fed into a place where a partial pressure belongs. Why is that a difficult error to catch?', '["It gives a not a number result, which a caller testing only for an error key will read as a valid answer.", "It gives a partial pressure above the total pressure, which the sum guard catches and reports as a composition error.", "It gives a rate several times too large, which the band label beside it then reports as the step above the one the case really belongs in.", "It gives a plausible answer rather than an obvious one, so the verdict shifts without anything on the screen looking wrong."]'::jsonb, 3, 'The engine keeps the two apart, labels which is which in its returned fields, and the chemistry panel puts them side by side. A ratio built from mole fractions is what catches a fugacity fed where a partial pressure belongs.'),
  ('corrosion', 'beginner', 'final', null, 14, 'One stream reports a combined rate that is 0.990899 of its smaller term. What shape of stream produces a figure that close to one?', '["One where the two terms are far apart, so the larger one adds almost nothing to the combined resistance.", "One where the two terms are nearly equal, so the series combination is almost the average of the two.", "One where the velocity is high enough that the transport term has stopped moving with it.", "One where the film multiplier is exactly one, so nothing is removed from the combination after it is formed."]'::jsonb, 0, 'It is the slowest of the six streams on both terms at once, and the engine puts its controlling margin at 107.879479, which is the largest of the six.'),
  ('corrosion', 'beginner', 'final', null, 15, 'On the stream whose combined rate is 0.990899 of its smaller term, which inputs would a corrosion engineer reach for to move the answer?', '["Temperature and carbon dioxide, because the reaction term is the larger of the two and a larger term is what sets the rate.", "The corrosion inhibitor efficiency alone, since it is the last lever.", "Velocity and line size, because the transport term is far below the reaction term and transport is what the engine names.", "Nothing, because a controlling margin of 107.879479 is outside the reporting margin and the engine declines to name a term."]'::jsonb, 2, 'Where transport controls, velocity and line size move this rate and the chemistry does not. Where the reaction controls, temperature and carbon dioxide move it and the flow does not.'),
  ('corrosion', 'beginner', 'final', null, 16, 'One exponent of the transport term is described in the digest as a property rather than as a typed constant. Which, and why?', '["The velocity exponent, measured at 0.800000000000, because it can be reached entirely from the outside by doubling the velocity at a fixed line diameter.", "The fugacity exponent, measured at 1.000000000000, because the term is exactly linear in fugacity and nothing needs to be typed to make it so.", "The diameter exponent, measured at 0.200000000000, because it enters the term the other way round from the velocity and has to be read off a halving.", "The coefficient in front of the term, measured at 2.450000000000, because it is read at unit velocity, unit diameter and unit fugacity."]'::jsonb, 1, 'The base two log of the doubling ratio in fugacity comes out at exactly one. The other three are held for literature and pinned against a literal in a third file.'),
  ('corrosion', 'beginner', 'final', null, 17, 'In the digest''s sweep of the transport term against velocity at four line diameters, both ratio columns are constant down the table and equal to each other. Why is that the claim being made?', '["It is what a linear term means, since a doubling in a term that is linear produces a fixed difference in the answer rather than a fixed ratio.", "It is what agreement with the vendored oracle means, since the oracle reaches exactly the same ratio through a route of its own that shares nothing.", "It is what the pin proves, since a constant measured at four diameters is measured four times over.", "It is what a power law in velocity means, and it is a statement about the shape of the term that holds whatever its constants turn out to be."]'::jsonb, 3, 'The measured velocity exponent is 0.800000000000 and the diameter exponent is 0.200000000000, both pinned against a literal in a third file.'),
  ('corrosion', 'beginner', 'final', null, 18, 'A screening declines to name either of the two rate terms. What has the engine done, and on what grounds?', '["It is a claim that the two mechanisms contribute equally at those conditions, and it is not a reporting decision of any kind.", "It is a refusal to compute the combined rate, and it is not something a reader should act on at all.", "It is a reporting decision taken when two nearly equal numbers would flip on floating point noise. It is not a claim about where transport stops mattering.", "It is the engine reporting that both terms sit inside the published validity band, and it is not a comparison between them."]'::jsonb, 2, 'The engine puts the margin on the rail beside the word, so a reader can see how far a given case sits from that boundary before acting on the name.'),
  ('corrosion', 'beginner', 'final', null, 19, 'A reported combined rate sits above one of the two terms it was built from. What can be said about that, and on what authority?', '["That the film multiplier has been applied to the wrong one of the two terms, which is the single arrangement question this module leaves open.", "That the arithmetic is wrong, and it can be said without reference to any source, because the claim needs no held constant.", "That the stream is in the sulphide regime, where the rate is retained only as an upper bound and may exceed either term.", "That the correlation has been run outside its published validity band, which the engine cannot detect and does not report."]'::jsonb, 1, 'The series identity is checked on every row the digest prints and held to twelve figures. Find the smaller term, and the printed combination should be near it and below it.'),
  ('corrosion', 'beginner', 'final', null, 20, 'At its own computed onset the film multiplier is exactly 1.000000000000 at every fugacity in the sweep. What kind of check is that?', '["A pin, since the value of one is a literal sitting in a third file and the measurement taken here is compared against that literal.", "An independent route, since the onset is reached by bisection and the factor by a closed form.", "A tolerance, since the agreement is quoted to twelve figures rather than as an exact equality and the size of the gap is what gets reported.", "A constant free invariant, since it tests the expression at its own boundary and needs no expected number from anywhere."]'::jsonb, 3, 'Below the onset the engine returns exactly one and the rate passes through untouched, which is why every capstone scenario in this course is set below its own onset.'),
  ('corrosion', 'beginner', 'final', null, 21, 'Hold a temperature of 60.000000 C and walk the carbon dioxide fugacity. At which of the swept fugacities is a film credited?', '["At 20.000000 bar and at 60.000000 bar, where the factors are 0.528864 and 0.273572.", "At every fugacity in the sweep, since the onset falls below 60.000000 C as soon as the fugacity leaves its lowest value.", "At 0.050000 bar and 0.200000 bar, where the onset is highest and the film therefore forms first.", "At none of them, since the shipped case runs at 60.000000 C and takes no film credit at all."]'::jsonb, 0, 'The onsets fall as the fugacity rises, from 132.297731 C at 0.050000 bar to 35.853960 C at 60.000000 bar. A stream sits below its onset at one fugacity and above it at another.'),
  ('corrosion', 'beginner', 'final', null, 22, 'Read the column of factors taken 20 degrees above each computed onset. What does it do across the sweep?', '["It holds at exactly one, since the multiplier is clamped and the clamp releases only well past the onset.", "It rises, from 0.337174 at the lowest fugacity in the sweep to 0.526907 at the highest of them, so a high pressure line keeps rather more of its rate.", "It falls, from 0.526907 at the lowest fugacity to 0.337174 at the highest, so the same step past the onset removes more at high fugacity.", "It is the same number at every fugacity in the sweep, which is the scale free property the whole onset table exists in order to demonstrate."]'::jsonb, 2, 'At 1.000000 bar it is 0.442281, at 2.000000 bar 0.423517 and at 5.000000 bar 0.399278. The factor at the onset itself is exactly one at every row.'),
  ('corrosion', 'beginner', 'final', null, 23, 'One line is screened at two operating pressures with nothing else changed. What can differ between the two answers?', '["Whether the rate is reported at all, because the onset expression refuses above the cap and the two pressures may straddle it.", "Whether any film credit is in the rate at all, because the onset moves with the fugacity and the printed rate alone will not say which case you have.", "Whether the wetting regime is read, because the film multiplier and the wetting factor are applied in the same step.", "Nothing, because the film multiplier depends on temperature alone and the temperature has not been touched."]'::jsonb, 1, 'Record the computed onset beside the rate whenever you copy a screening down. It is the number that says whether the film is in the answer.'),
  ('corrosion', 'beginner', 'final', null, 24, 'Why is the computed onset teachable in this course when the published turning temperature is not?', '["It is measured out of the engine''s own behaviour by bisection and cross checked against a closed form, and it is still not a sourced temperature.", "It is exported by name, so a declaration and a behaviour can be compared, which is what makes a figure teachable here.", "It is one of the four range guards the engine enforces, so it is a limit the module can defend rather than a fit it cannot.", "It is graded in the capstone, which is the test a figure has to pass before a lesson may quote it."]'::jsonb, 0, 'The three constants of the expression that produces it are held for literature, and so is the temperature at which the published correlation turns protective.'),
  ('corrosion', 'beginner', 'final', null, 25, 'A help page states that the protective film appears at a single round temperature. What is wrong with that?', '["It is right on any stream sitting below the fugacity cap and wrong on any stream above it, where the coefficient is held flat instead.", "It is right for the reaction term and wrong for the combined rate, which is precisely the arrangement question this module declines to settle.", "It is wrong because the engine refuses to compute an onset at all and reports only the multiplier.", "It is right at one fugacity and wrong at every other, because the onset moves by 96.443771 degrees Celsius across the swept band."]'::jsonb, 3, 'The panel prints the computed onset for the conditions set rather than a constant, and the figure moves as the pressure or the composition changes.'),
  ('corrosion', 'beginner', 'final', null, 26, 'A screening shows a multiplier of exactly one while the temperature sits above the computed onset on the same panel. What should a reader do?', '["Take the multiplier, since it is the value that actually reached the rate and the onset is reported for information only.", "Take the onset, since it is found by bisection and cross checked against a closed form while the multiplier is read once.", "Trust neither figure until they have found out why, because the two cannot both be right.", "Take both, since a multiplier of one above the onset is what the clamp produces whenever the fugacity is below the cap."]'::jsonb, 2, 'Three readings are worth telling apart. A multiplier of one below the onset means the film is not credited, a multiplier below one means the rate you are reading is lower for it, and the third combination is a contradiction.'),
  ('corrosion', 'beginner', 'final', null, 27, 'Two values a ten thousandth of a pH unit apart, 3.999900 and 4.000000, are handed to the correction. How do the two answers differ?', '["A refusal from both, since the reference guard is applied at or below its own value rather than strictly below it.", "A refusal from the first, carrying the reference of 4.000000, and a factor of exactly 1.000000000000 from the second.", "A factor from both, the first extrapolated from the slope and marked as outside the band the correction was fitted over.", "A factor of 1.000000000000 from the first, since the correction is clamped at the reference, and the same from the second."]'::jsonb, 1, 'The boundary is sharp and it is meant to be. What the published correction does on the lower side of it carries no source in this repository.'),
  ('corrosion', 'beginner', 'final', null, 28, 'One of the engine''s worked streams runs a rate of 0.840204 mm/yr at an in situ pH of 5.500000. Where does the same stream sit at 4.500000 and at 6.000000?', '["At 0.472482 mm/yr and 2.656960 mm/yr, so the rate rises at every step up the column as the water becomes less acid.", "At 2.656960 mm/yr and 0.840204 mm/yr, since the correction is flat across the middle of the band.", "At 1.494118 mm/yr and 0.149412 mm/yr, which are the values one whole pH unit either side of the stated figure.", "At 2.656960 mm/yr and 0.472482 mm/yr, so the rate falls at every step up the column."]'::jsonb, 3, 'The column is strictly falling, and at 5.000000 the same stream sits at 1.494118 mm/yr. Every step is a smaller drop than the one above it.'),
  ('corrosion', 'beginner', 'final', null, 29, 'Three different things are refused at the pH door and the messages are not the same. Which description is right?', '["A blank box and a pH of 14.500000 give back the same message as each other, and a pH below 4.000000 gives a factor with a warning attached to it.", "A blank box asks for a finite figure, a pH of 14.500000 names the band of nought to fourteen, and a pH below 4.000000 names the reference.", "All three give the same message, since every refusal in this module names the input and the value that failed.", "A blank box gives a factor of one, a pH of 14.500000 is clamped to fourteen, and a pH below 4.000000 is refused."]'::jsonb, 1, 'The range guard and the reference guard are separate and they say different things. The reference guard sits inside the range and refuses a chemically valid pH.'),
  ('corrosion', 'beginner', 'final', null, 30, 'The pH door returns a factor and the reference it was taken against. Which parts of that correction carry no source in this repository?', '["The slope, the reference itself, and what the correlation does below the reference.", "The reference alone, since a slope measured by bisection is a behaviour rather than a fitted number.", "The slope alone, since the reference is enforced as a range guard and a guard the engine enforces is one it can defend.", "Neither, since both are exported by name and an exported constant is one the module has a source for."]'::jsonb, 0, 'They are measured out of the engine''s behaviour and pinned against a literal in a third file, so the module is using what it declares. No source here says whether the declared values are the published ones.'),
  ('corrosion', 'beginner', 'final', null, 31, 'At the pH reference the factor is exactly 1.000000, and the digest says that is by definition rather than by a clamp. What does that mean?', '["The engine tests the pH against the reference and substitutes one whenever the two agree, which is what a clamp at a boundary does.", "The factor is clamped at one from above in the same way the film multiplier is, so no correction anywhere can ever raise a rate.", "The reference was chosen after the fact as the pH at which the measured factor happened to come out at one.", "The correction is the ratio of the water you have to the water the fit was made on, so at the fitted condition it cannot be anything else."]'::jsonb, 3, 'Above the reference the factor falls below one, which reduces the rate. Below the reference the engine returns no factor at all.'),
  ('corrosion', 'beginner', 'final', null, 32, 'The studio prints the engine''s own warning about the corrosion inhibitor programme on its shipped case. What figure does that warning state for the metal loss?', '["5.203611 times the datasheet number, which is the uninhibited rate on that case.", "1.000000 times the datasheet number, since the datasheet efficiency is what the case was run at.", "1.45 times the datasheet number, from an effective protection of 85.5 percent.", "6.896552 times the datasheet number, which is the ratio the shear verdict produces on the same case."]'::jsonb, 2, 'The datasheet efficiency is 90.000000 percent and the availability is 95.000000 percent, so the effective protection is 85.500000 percent and the shortfall is 4.500000 percentage points.'),
  ('corrosion', 'beginner', 'final', null, 33, 'Why do all three capstones in this course state their conditions in the engine''s units rather than in the studio''s?', '["Because one of the studio''s conversion factors is truncated, so grading a learner on which rounding an app happens to carry would measure the app instead of the corrosion.", "Because the engine refuses any input it did not convert itself, so a figure in field units would never reach the correlation.", "Because the studio''s conversions are applied twice on the way out, so a figure taken through them cannot be reproduced by hand.", "Because the capstone grades a corrosion rate, and a rate is only reproducible when the conditions behind it are in correlation units."]'::jsonb, 0, 'The studio divides a psig pressure by 14.5038 where the engine exports 14.503773800722, which sits 1.910e-9 above what the definitions of the bar and of the pound force give.'),
  ('corrosion', 'beginner', 'final', null, 34, 'The shipped case reports an uninhibited rate. What is it in both units, and what does it mean?', '["5.203611 mm/yr, which is 29.705656 mpy, and it is the rate the datasheet efficiency alone would give.", "5.203611 mm/yr, which is 204.866591 mpy, and it is the same case with no corrosion inhibitor credit at all.", "0.754524 mm/yr, which is 204.866591 mpy, and it is the rate before the pH factor has been applied.", "9.253475 mm/yr, which is 204.866591 mpy, and it is the series combination of the two terms before any correction at all."]'::jsonb, 1, 'The reported rate on the same screen is 0.754524 mm/yr, and the corrosion inhibitor credit of 85.500000 percent is the whole of what separates the two.'),
  ('corrosion', 'beginner', 'final', null, 35, 'At 60 ft per second the engine reports two rates side by side. What are they and why are both there?', '["13.080024 mm/yr as an upper bound and 1.896603 mm/yr as a best estimate, so the reader has a bracket rather than a value.", "13.080024 mm/yr from the correlation and 1.896603 mm/yr from the vendored oracle, so the two derivations can be compared.", "13.080024 mm/yr at the new velocity and 1.896603 mm/yr at the shipped one, so the reader can see what the change did.", "13.080024 mm/yr with the credit removed and 1.896603 mm/yr with it kept, so the cost of the shear verdict is visible rather than implied."]'::jsonb, 3, 'The wall shear there is 362.474888 Pa against the measured stripping threshold of 100.000000 Pa, and the film risk turns high. No new correlation was invented to do it: the credit is simply not taken.'),
  ('corrosion', 'beginner', 'final', null, 36, 'At 60 ft per second the engine reports the rate with the corrosion inhibitor credit removed beside the rate with it kept. What is the ratio between the two, and what happens to the remaining life?', '["2.779300, and the remaining life falls to 0.242737 yr.", "6.896552, and the remaining life is withheld because the model no longer applies at that velocity.", "6.896552, and the remaining life falls from 4.207953 yr to 0.242737 yr.", "1.163506, and the remaining life falls from 20.000000 yr to 4.207953 yr."]'::jsonb, 2, 'The binding constraint becomes the wall shear on the corrosion inhibitor film, and the engine''s own sentence says that slowing the line changes this answer before anything else does.'),
  ('corrosion', 'beginner', 'final', null, 37, 'Move the in situ pH of the shipped case to 4.0. What is the remaining life there?', '["2.366306 yr, against 4.207953 yr at the shipped value.", "0.242737 yr, against 4.207953 yr at the shipped value, since a lower pH removes the corrosion inhibitor credit.", "4.207953 yr, unchanged, since the pH factor reaches the reported rate through the wetting regime alone.", "20.000000 yr, since at the reference the correction is exactly one and the case meets its design life."]'::jsonb, 0, 'The rate at 4.0 is 1.341754 mm/yr against 0.754524 mm/yr at 4.5, and the binding constraint stays with the corrosion allowance against the design life.'),
  ('corrosion', 'beginner', 'final', null, 38, 'The studio''s shipped case types a density of 56 lb/ft3 and a viscosity of 1 cp. What reaches the engine?', '["56 kg/m3 and 1.000000 mPa s, since the density conversion is applied on the way back out rather than on the way in and never before.", "897.036000 kg/m3 and 1.000000 mPa s.", "897.036000 kg/m3 and 0.001000 mPa s, the viscosity being divided by a thousand as well as multiplied by it.", "897.036000 kg/m3 and 1.000000 mPa s, both of which the engine then converts again before the wall shear is formed."]'::jsonb, 1, 'Both figures feed this module''s own Reynolds number, which on that case is 416686.8569. The engine works in kilograms a cubic metre and pascal seconds because that is what the correlations behind it are published in.'),
  ('corrosion', 'beginner', 'final', null, 39, 'A learner writes that this module computes the friction factor for a line. What is missing from that sentence?', '["That the friction factor is held for literature, which is the standing of every constant in this engine.", "That the friction factor is read across from the line sizing module, which is where every friction factor on this platform is computed.", "That the two courses agree on the same pipe whenever the branch is turbulent and part company only in the laminar branch.", "That it is this module''s own friction factor, and that the line sizing course computes its own with a different correlation and a different transition."]'::jsonb, 3, 'The two will not agree on the same pipe and the engine says so in its own docstring. Removing the duplicate is a cross module decision and the repair deliberately left it alone.'),
  ('corrosion', 'beginner', 'final', null, 40, 'Why does this course insist on the words corrosion inhibitor rather than the bare word?', '["Because the bare word already means a hydrate inhibitor in the Flow Assurance course, dosed in mass fraction of the water phase.", "Because the bare word already means a scale inhibitor in the Production Chemistry course, which is dosed continuously.", "Because the engine''s own field names use the longer form, and a bank question has to match the field name a learner will eventually read on the screen.", "Because the bare word would be read as the corrosion allowance, which is the other quantity the same rail carries."]'::jsonb, 0, 'Here it is a filming amine on the steel with an efficiency and an availability. The two are different chemicals doing different jobs in different phases.'),
  ('corrosion', 'beginner', 'final', null, 41, 'A lesson in this course needs to mention wall loss from entrained solids. What must it carry with the mention?', '["The name of the live course that owns the criterion, and nothing further, since naming an owner is the whole of what a scope seam requires.", "The wall shear this module computes, since that is the one quantity an erosional velocity limit would have to be compared against.", "The words mechanical erosion or erosional wall loss, and the statement that this engine has no erosional velocity criterion at all.", "A note that the criterion is held for literature, in the same way the film stripping threshold is held."]'::jsonb, 2, 'The bare word already means a geological process in the Basin Modelling course. The Casing & Tubing Design course owns the erosional velocity criterion, and Nodal Analysis and Gas Well Deliverability cite it.'),
  ('corrosion', 'beginner', 'final', null, 42, 'One live course points at this one. Which, and what does it say about corrosion?', '["The Pipeline & Line Sizing course, which adds a corrosion allowance to a wall and leaves the rate that consumes it to this module.", "The Well Integrity and P&A course, which states in its own scope that it carries no corrosion model, no wall loss and no remaining life.", "The Fluid Properties course, which owns fugacity and hands the partial pressure comparison over to this one.", "The Casing & Tubing Design course, which owns the erosional velocity criterion and defers the film question here."]'::jsonb, 1, 'This course fills exactly that refusal. A barrier envelope is a pressure containment argument and a corrosion allowance is a thickness this studio divides by a rate, and no lesson may write one as the other.');
